import pandas as pd
import os

# Load all experiment files
files = {}
for i in range(1, 5):
    path = f"experiment_{i}_csv"
    # Find the actual path in the environment
    for f in os.listdir('.'):
        if f.startswith(f'experiment_{i}') and f.endswith('.csv'):
            path = f
            break
    try:
        files[i] = pd.read_csv(path)
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(files[i].columns)}")
        print(f"Shape: {files[i].shape}")
        print(f"exp_id unique: {files[i]['exp_id'].unique() if 'exp_id' in files[i].columns else 'N/A'}")

        # Show any intervention columns
        int_cols = [c for c in files[i].columns if c.startswith('do_')]
        if int_cols:
            print(f"Intervention cols: {int_cols}")
            for c in int_cols:
                if files[i][c].notna().any():
                    print(f"  {c}: {files[i][c].dropna().unique()}")

        # Correlations with outcome
        if 'WaterClarityScore' in files[i].columns:
            corr = files[i].corr(numeric_only=True)['WaterClarityScore'].drop('WaterClarityScore').sort_values(key=abs, ascending=False)
            print(f"Correlations with WaterClarityScore:\n{corr.round(3)}")

            # Group by intervention if present
            if 'do_LineFlushRate' in files[i].columns:
                grouped = files[i].groupby('do_LineFlushRate', observed=True).agg({
                    'WaterClarityScore': 'mean',
                    'MetalColorimetry': 'mean',
                    'ResidualChlorine': 'mean',
                    'LineFlushRate': 'mean',
                    'unit_id': 'count'
                })
                print(f"\nGrouped by LineFlushRate intervention:")
                print(grouped.round(2))
    except Exception as e:
        print(f"Error loading experiment {i}: {e}")
